package dev.sigmarix.quests.client;
import dev.sigmarix.quests.*;import java.util.*;import net.minecraft.client.gui.GuiScreen;import net.minecraft.util.StatCollector;
final class QuestRewardTableSettingsScreen extends QuestConfigScreen {
    private final QuestCore.Book book;private final String id;private final QuestCore.LootSettings settings;
    QuestRewardTableSettingsScreen(GuiScreen parent,QuestCore.Book book,String id){super(parent);this.book=book;this.id=id;QuestCore.LootSettings current=book.lootSettings.get(id);settings=current==null?new QuestCore.LootSettings():QuestService.JSON.fromJson(QuestService.JSON.toJson(current),QuestCore.LootSettings.class);}
    protected String title(){return "FTB Quests";}
    private String tr(String key){return StatCollector.translateToLocal(key);}
    protected List<Entry> entries(){List<Entry> rows=new ArrayList<Entry>();rows.add(new Entry("FTB Quests",tr("ftbquests.title"),()->settings.name,()->0xFFAA49,(b,g)->mc.displayGuiScreen(new QuestValueScreen(this,settings.name,0xFFAA49,256,s->settings.name=s))));rows.add(new Entry("FTB Quests",tr("ftbquests.reward_table.empty_weight"),()->Integer.toString(settings.emptyWeight),()->0xAA5AE8,(b,g)->mc.displayGuiScreen(new QuestValueScreen(this,Integer.toString(settings.emptyWeight),0xAA5AE8,10,s->settings.emptyWeight=Integer.parseInt(s)))));rows.add(new Entry("FTB Quests",tr("ftbquests.reward_table.loot_size"),()->Integer.toString(settings.rolls),()->0xAA5AE8,(b,g)->mc.displayGuiScreen(new QuestValueScreen(this,Integer.toString(settings.rolls),0xAA5AE8,10,s->settings.rolls=Integer.parseInt(s)))));rows.add(new Entry(tr("item.ftbquests.lootcrate.name"),tr("ftbquests.reward_table.loot_crate.string_id"),()->settings.alias,()->0xFFAA49,(b,g)->mc.displayGuiScreen(new QuestValueScreen(this,settings.alias,0xFFAA49,128,s->settings.alias=s))));rows.add(new Entry(tr("item.ftbquests.lootcrate.name"),tr("ftbquests.reward_table.loot_crate.color"),()->settings.color,()->QuestPresentation.color(settings.color),(b,g)->mc.displayGuiScreen(new QuestValueScreen(this,settings.color,0xFFAA49,8,s->{QuestPresentation.color(s);settings.color=s;}))));rows.add(new Entry(tr("item.ftbquests.lootcrate.name"),tr("ftbquests.reward_table.loot_crate.glow"),()->Boolean.toString(settings.glow),()->settings.glow?0x33AA33:0xD52834,(b,g)->settings.glow=!settings.glow));return rows;}
    protected void save(){if(settings.emptyWeight<0 || settings.emptyWeight>1000000 || settings.rolls<1 || settings.rolls>64)throw new IllegalArgumentException("Invalid loot settings");book.lootSettings.put(id,settings);}
}
